importScripts("extension-context.js");
try {
  importScripts("local-config.js");
} catch {
  // Generated by the local installer.
}

const cvFit = globalThis.cvFitBridge;
const submissionsEndpoint = `${cvFit.protocol.bridgeOrigin}/cv-fit-submissions`;
const REQUEST_TIMEOUT_MS = 10_000;

const requestBridge = async (message) => {
  const isStart = message.type === cvFit.protocol.submitTaskMessage;
  if (!isStart && !message.submissionId) {
    return { ok: false, error: "Submission ID is missing" };
  }
  const endpoint = isStart
    ? submissionsEndpoint
    : `${submissionsEndpoint}/${encodeURIComponent(message.submissionId)}`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(endpoint, {
      cache: "no-store",
      method: isStart ? "POST" : "GET",
      signal: controller.signal,
      headers: {
        "Content-Type": "application/json",
        "X-CV-Fit-Bridge-Token": cvFit.protocol.bridgeToken,
      },
      ...(isStart ? { body: JSON.stringify({ jobUrl: message.jobUrl }) } : {}),
    });
    const body = await response.json().catch(() => ({}));
    return response.ok && body.ok
      ? { ok: true, ...(body.submission ? { submission: body.submission } : {}) }
      : { ok: false, error: body.error || `Request failed with status ${response.status}` };
  } catch (error) {
    return {
      ok: false,
      error: error.name === "AbortError"
        ? "The local bridge did not respond within 10 seconds"
        : error.message,
    };
  } finally {
    clearTimeout(timer);
  }
};

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (![cvFit.protocol.submitTaskMessage, cvFit.protocol.getTaskStatusMessage].includes(message?.type)) {
    return false;
  }
  if (!cvFit.protocol.bridgeToken) {
    sendResponse({ ok: false, error: "Bridge token is not configured in extension/local-config.js" });
    return false;
  }
  requestBridge(message).then(sendResponse, (error) => {
    sendResponse({ ok: false, error: error.message });
  });
  return true;
});
